<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $meds=db()->query('SELECT m.*,COALESCE(SUM(b.units_remaining),0) stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id WHERE m.active=1 GROUP BY m.id ORDER BY m.name')->fetchAll(); $customers=db()->query('SELECT id,name,phone FROM customers ORDER BY name')->fetchAll(); function e2(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fast POS · <?=e2(APP_NAME)?></title><link rel="stylesheet" href="style.css"><style>.pos-search{font-size:18px;padding:16px;border-radius:14px}.hint{margin:8px 0 16px;color:#64748b;font-size:12px}.shortcut{display:inline-flex;align-items:center;margin-left:8px;padding:2px 7px;border:1px solid #cbd5e1;border-radius:6px;background:#f8fafc;color:#475569;font:700 10px/1.2 system-ui}.result{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:14px 0;border-bottom:1px solid #e2e8f0}.result small,.item small{display:block;color:#64748b;margin-top:4px}.sell-buttons{display:flex;gap:6px}.mini{min-width:82px;padding:8px 10px;font-size:11px}.cart-panel{position:sticky;top:15px}.cartrow{display:grid;grid-template-columns:1fr 70px 100px 30px;gap:10px;align-items:center;padding:12px 0;border-bottom:1px solid #e2e8f0}.item-actions{display:flex;gap:8px;align-items:center;margin-top:8px;flex-wrap:wrap}.item-actions label{font-size:11px;color:#64748b}.item-actions input{width:70px;padding:7px}.discount-line{font-size:11px;color:#64748b;margin-top:4px}.payment-box{margin-top:18px;padding:16px;border-radius:14px;background:#f8fafc;border:1px solid #e2e8f0}.pay-label{display:block;font-size:11px;text-transform:uppercase;color:#64748b;font-weight:700;margin-bottom:6px}.payment-total{font-size:28px;font-weight:800;margin:8px 0 14px}.change-preview{margin-top:8px;padding:10px 12px;border-radius:10px;background:#ecfdf5;color:#166534;font-weight:700}.checkout{width:100%;font-size:16px;padding:14px}@media(max-width:900px){.cart-panel{position:static}.result{align-items:flex-start;flex-direction:column}.sell-buttons{width:100%}.mini{flex:1}.cartrow{grid-template-columns:1fr 60px 90px 25px}}@media print{body>*{display:none!important}}</style></head><body><header><div class="brand">💊 <?=e2(APP_NAME)?></div><nav><a href="index.php?action=dashboard">Dashboard</a><a class="active" href="pos.php">POS</a><a href="manage.php">Management</a></nav><div class="user-info">👤 <?=e2(current_user()['username']??'')?> · <?=e2(ucfirst(current_user()['role']??''))?> · <a href="logout.php">Logout</a></div></header><main><div class="page-title"><div><div class="eyebrow">POINT OF SALE</div><h1>Fast Sale</h1><p>Search or scan a medicine, choose the unit, and set a discount for each item.</p></div><div>● Ready</div></div><div class="pos"><section class="panel"><div><input id="search" class="pos-search" autocomplete="off" placeholder="🔎 Search medicine, generic name or barcode" autofocus><span class="shortcut">F2</span></div><div class="hint">Cost and selling price are visible. Expired stock is blocked automatically.</div><div id="results"></div></section><section class="panel cart-panel"><div class="cart-head"><div><h2>Current Sale</h2><span id="count">0 units</span></div><button class="clear-btn" onclick="clearCart()">Clear <span class="shortcut">Ctrl+Backspace</span></button></div><div id="cart"></div><div class="totals"><div>Subtotal <b>Rs. <span id="subtotal">0.00</span></b></div><div>Item discounts <b>Rs. <span id="discountTotal">0.00</span></b></div><div class="grand">Total <strong>Rs. <span id="total">0.00</span></strong></div></div><div class="payment-box"><span class="pay-label">Payment</span><div class="payment-total">Rs. <span id="payTotal">0.00</span></div><div><select id="payment" onchange="paymentChanged()"><option value="cash">💵 Cash F8</option><option value="card">💳 Card F9</option><option value="credit">👤 Credit F10</option></select></div><div style="margin-top:10px"><input id="paid" type="number" min="0" step="0.01" placeholder="Amount received"><span class="shortcut">F6</span></div><div id="changePreview"></div><div id="customerWrap" style="display:none;margin-top:10px"><label class="pay-label">Customer for credit sale</label><select id="customer"><option value="">Select customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e2($c['name'])?><?= $c['phone']?' — '.e2($c['phone']):'' ?></option><?php endforeach;?></select></div></div><button class="btn checkout" onclick="checkout()">Complete Sale → <span class="shortcut">F12</span> <span class="shortcut">Ctrl+Enter</span></button></section></div></main><script>const medicines=<?=json_encode($meds,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let cart=[];const fmt=n=>Number(n).toFixed(2);function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}function pack(m,type){let u=Number(m.units_per_strip)||1,s=Number(m.strips_per_box)||1,p=Number(m.retail_unit_price)||0,c=Number(m.purchase_price)||0;if(type==='box')return{label:'Box',units:u*s,price:p*u*s,cost:c*u*s};if(type==='strip')return{label:'Strip',units:u,price:p*u,cost:c*u};return{label:m.unit_name||'Tablet',units:1,price:p,cost:c};}function renderResults(){const q=document.getElementById('search').value.toLowerCase().trim();const rs=medicines.filter(m=>(m.name+' '+(m.generic_name||'')+' '+(m.strength||'')+' '+(m.barcode||'')).toLowerCase().includes(q)).slice(0,15);document.getElementById('results').innerHTML=rs.map(m=>`<div class="result"><span><b>${esc(m.name)}</b><small>${esc((m.generic_name||'')+' '+(m.strength||''))} · Cost Rs.${fmt(m.purchase_price)} · Sell Rs.${fmt(m.retail_unit_price)} · Stock ${m.stock}${m.barcode?' · '+esc(m.barcode):''}</small></span><div class="sell-buttons"><button class="btn mini" onclick="add(${m.id},'box')">BOX<br><small>Cost Rs.${fmt(pack(m,'box').cost)} · Sell Rs.${fmt(pack(m,'box').price)}</small></button><button class="btn mini" onclick="add(${m.id},'strip')">STRIP<br><small>Cost Rs.${fmt(pack(m,'strip').cost)} · Sell Rs.${fmt(pack(m,'strip').price)}</small></button><button class="btn mini" onclick="add(${m.id},'unit')">${esc((m.unit_name||'TABLET').toUpperCase())}<br><small>Cost Rs.${fmt(m.purchase_price)} · Sell Rs.${fmt(pack(m,'unit').price)}</small></button></div></div>`).join('');}function add(id,type){const m=medicines.find(x=>Number(x.id)===Number(id));if(!m||Number(m.stock)<1)return;const p=pack(m,type);if(p.units>Number(m.stock))return alert('Not enough stock for one '+p.label+'.');const key=id+'-'+type;let x=cart.find(v=>v.key===key);if(x){if((x.qty+1)*x.units>Number(m.stock))return alert('Not enough stock.');x.qty++;}else cart.push({key,id:Number(id),name:m.name,type,units:p.units,price:p.price,qty:1,max:Number(m.stock),unitLabel:p.label,cost:p.cost,discountPct:0});renderCart();}function remove(i){cart.splice(i,1);renderCart();}function setQty(i,v){const n=Math.max(1,parseInt(v)||1);if(n*cart[i].units>cart[i].max)return alert('Not enough stock.');cart[i].qty=n;renderCart();}function setDiscount(i,v){cart[i].discountPct=Math.min(100,Math.max(0,Number(v)||0));renderCart();}function renderCart(){document.getElementById('cart').innerHTML=cart.length?cart.map((x,i)=>{const gross=x.price*x.qty,disc=gross*x.discountPct/100,total=gross-disc;return `<div class="cartrow"><div class="item"><b>${esc(x.name)}</b><small>Cost Rs. ${fmt(x.cost/x.units)} / unit · Sell Rs. ${fmt(x.price/x.units)} / unit · ${x.qty} × ${x.unitLabel}</small><div class="item-actions"><label>Discount % <input type="number" min="0" max="100" step="0.01" value="${fmt(x.discountPct)}" data-discount-index="${i}"></label><span class="discount-line">Discount: Rs. ${fmt(disc)} · Line total: Rs. ${fmt(total)}</span></div></div><input type="number" min="1" value="${x.qty}" data-qty-index="${i}"><b>Rs. ${fmt(total)}</b><button class="remove" data-remove-index="${i}">×</button></div>`}).join(''):'<div class="empty"><div class="empty-icon">🛒</div><b>No items yet</b><small>Search or scan a medicine, then choose Box, Strip, or Tablet.</small></div>';document.querySelectorAll('[data-discount-index]').forEach(el=>el.addEventListener('change',()=>setDiscount(Number(el.dataset.discountIndex),el.value)));document.querySelectorAll('[data-qty-index]').forEach(el=>el.addEventListener('change',()=>setQty(Number(el.dataset.qtyIndex),el.value)));document.querySelectorAll('[data-remove-index]').forEach(el=>el.addEventListener('click',()=>remove(Number(el.dataset.removeIndex))));const s=cart.reduce((a,x)=>a+x.price*x.qty,0),d=cart.reduce((a,x)=>a+(x.price*x.qty*x.discountPct/100),0),t=Math.max(0,s-d);document.getElementById('count').textContent=cart.reduce((a,x)=>a+x.units*x.qty,0)+' units';document.getElementById('subtotal').textContent=fmt(s);document.getElementById('discountTotal').textContent=fmt(d);document.getElementById('total').textContent=fmt(t);document.getElementById('payTotal').textContent=fmt(t);previewChange();}function paymentChanged(){const credit=document.getElementById('payment').value==='credit';document.getElementById('customerWrap').style.display=credit?'block':'none';if(!credit)document.getElementById('customer').value='';previewChange();}function previewChange(){const t=Number(document.getElementById('total').textContent)||0,p=Number(document.getElementById('paid').value)||0,m=document.getElementById('payment').value,e=document.getElementById('changePreview');if(m==='cash'&&p>t)e.innerHTML='<div class="change-preview">Change: Rs. '+fmt(p-t)+'</div>';else if(m==='credit'&&p<t)e.innerHTML='<div class="change-preview" style="background:#fff7ed;color:#9a3412">Balance due: Rs. '+fmt(t-p)+'</div>';else e.innerHTML='';}function clearCart(){cart=[];renderCart();document.getElementById('search').focus();}function checkout(){if(!cart.length)return alert('Cart is empty.');const method=document.getElementById('payment').value,customer=document.getElementById('customer').value;if(method==='credit'&&!customer)return alert('Please select a customer for a credit sale.');const sub=cart.reduce((a,x)=>a+x.price*x.qty,0),discount=cart.reduce((a,x)=>a+x.price*x.qty*x.discountPct/100,0),total=Math.max(0,sub-discount),p=document.getElementById('paid').value,paid=p===''?(method==='credit'?0:total):Math.max(0,Number(p)||0);if(paid>total)return alert('Amount received cannot exceed the sale total.');if(method!=='credit'&&paid<total)return alert('For cash/card sales, amount received must cover the total.');const items=cart.map(x=>({id:x.id,name:x.name,qty:x.units*x.qty,price:x.price/x.units}));const f=document.createElement('form');f.method='post';f.action='index.php?action=sale';[['items',JSON.stringify(items)],['discount',discount],['discount_pct',0],['payment_method',method],['paid',paid],['customer_id',customer]].forEach(([n,v])=>{const i=document.createElement('input');i.type='hidden';i.name=n;i.value=v;f.appendChild(i)});document.body.appendChild(f);f.submit();}const search=document.getElementById('search'),paid=document.getElementById('paid'),payment=document.getElementById('payment'),customer=document.getElementById('customer');let selectedResult=-1;function resultButtons(){return [...document.querySelectorAll('#results .sell-buttons button')]}function focusResult(){const rs=[...document.querySelectorAll('#results .result')];rs.forEach((r,i)=>r.style.outline=i===selectedResult?'2px solid #4774d9':'');if(rs[selectedResult])rs[selectedResult].scrollIntoView({block:'nearest'});}search.addEventListener('keydown',e=>{const rs=[...document.querySelectorAll('#results .result')];if(e.key==='ArrowDown'){e.preventDefault();selectedResult=Math.min(selectedResult+1,rs.length-1);focusResult();}else if(e.key==='ArrowUp'){e.preventDefault();selectedResult=Math.max(selectedResult-1,0);focusResult();}else if(e.key==='Enter'&&selectedResult>=0){e.preventDefault();const buttons=rs[selectedResult].querySelectorAll('button');if(buttons.length)buttons[2].focus();}else if(e.key==='Tab'){selectedResult=-1;}});document.addEventListener('keydown',e=>{if(e.key==='F2'){e.preventDefault();search.focus();search.select();}else if(e.key==='F6'){e.preventDefault();paid.focus();paid.select();}else if(e.key==='F8'){e.preventDefault();payment.value='cash';paymentChanged();paid.focus();}else if(e.key==='F9'){e.preventDefault();payment.value='card';paymentChanged();paid.focus();}else if(e.key==='F10'){e.preventDefault();payment.value='credit';paymentChanged();customer.focus();}else if(e.key==='F12'||(e.ctrlKey&&e.key==='Enter')){e.preventDefault();checkout();}else if(e.ctrlKey&&e.key==='Backspace'){e.preventDefault();clearCart();}else if(e.key==='Escape'){e.preventDefault();search.focus();search.select();}});search.addEventListener('input',()=>{selectedResult=-1;renderResults();});paid.addEventListener('input',previewChange);renderResults();renderCart();</script></body></html>